/**
 * Very minimal glue to bind the autogenerated code to the common HttpClient.
 *
 * @flow
 */
import HttpClient from 'silk-http-client';
import type { Request } from 'silk-http-client';

export default class ApiClient extends HttpClient {
  // XXX: This is a hack since we still do not support true GET requests...
  _apiRequest(method: string, url: string): Promise<any> {
    return this.request([url, { method }]);
  }

  _apiRequestWithBody(method: string, url: string, body: {[key: string]: any}): Promise<any> {
    // Wire up to the underlying class ...
    return this.request([url, {
      body,
      method,
    }]);
  }

  async _sendRequest(
    id: string,
    req: Request
  ): Promise<any> {
    let res = await super._sendRequest(id, req);
    // All our internal API(s) use JSON response bodies.
    let resBody = await res.json();
    this._log(`Body (${id}) ${req[1].method} ${req[0]}`);
    return resBody;
  }
}
